import java.io.BufferedReader;
import java.io.File;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;
import java.io.StringWriter;

public class Main {
    public static void main(String[] args) {
        StringWriter report = new StringWriter();   // a "file" that lives in memory
        report.write("DAILY FLEET REPORT\n");
        int count = 0;
        try (BufferedReader in = new BufferedReader(new FileReader("fleet_backup.txt"))) {
            String line = in.readLine();
            while (line != null) {
                String[] part = line.split(",");
                count++;
                report.write(count + ". " + part[1] + " (" + part[0] + ") - " + part[2] + "\n");
                line = in.readLine();
            }
        } catch (IOException e) {
            System.out.println("Cannot read: " + e.getMessage());
        }
        report.write("Total vehicles: " + count + "\n");

        String text = report.toString();     // everything written so far
        System.out.print(text);              // 1) show it on screen
        try (FileWriter out = new FileWriter("report.txt")) {
            out.write(text);                 // 2) save the SAME text
        } catch (IOException e) {
            System.out.println("Cannot write: " + e.getMessage());
        }
        File saved = new File("report.txt");
        System.out.println("report.txt size: " + saved.length() + " bytes");
    }
}

