public class DispatchThread extends Thread {      // a Thread that does dispatch work
    private Vehicle vehicle;
    private int trips;
    private double collected = 0;
    private String ranOn = "not run yet";

    public DispatchThread(Vehicle vehicle, int trips) {
        super(vehicle.getPlateNumber());   // the thread's name is the plate
        this.vehicle = vehicle;
        this.trips = trips;
    }

    @Override
    public void run() {                    // the job this thread does
        ranOn = Thread.currentThread().getName();
        for (int i = 1; i <= trips; i++) {
            collected = collected + vehicle.quoteFare(5);
            try {
                Thread.sleep(100);         // one trip takes time (0.1 second)
            } catch (InterruptedException e) {
                return;                    // stop early if interrupted
            }
        }
    }

    public double getCollected() { return collected; }
    public String getRanOn() { return ranOn; }
}

public class Main {
    public static void main(String[] args) {
        System.out.println("main() runs on thread: " + Thread.currentThread().getName());
        Vehicle jeep = new Jeepney("NXA 123", "Mang Ramon", "Monumento-Divisoria");
        DispatchThread t = new DispatchThread(jeep, 5);

        System.out.println("Before start(): " + t.getState());
        t.start();                         // a NEW thread begins run()
        try {
            t.join();                      // main waits here until t is finished
        } catch (InterruptedException e) {
            System.out.println("main was interrupted");
        }
        System.out.println("After join(): " + t.getState());
        System.out.println(t.getName() + " ran on thread: " + t.getRanOn());
        System.out.println("Collected after 5 trips: P" + t.getCollected());
    }
}

