import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<DispatchThread> crew = new ArrayList<>();
        crew.add(new DispatchThread(new Jeepney("NXA 123", "Mang Ramon", "Monumento-Divisoria"), 5));
        crew.add(new DispatchThread(new Tricycle("TRC 456", "Kuya Ben", "Bagong Silang TODA"), 5));
        crew.add(new DispatchThread(new Bus("BUS 789", "Aling Rosa", 50), 5));

        long begin = System.currentTimeMillis();
        for (DispatchThread t : crew) {
            t.start();                     // all three run AT THE SAME TIME
        }
        for (DispatchThread t : crew) {
            try {
                t.join();                  // wait for each one to finish
            } catch (InterruptedException e) {
                System.out.println("main was interrupted");
            }
        }
        long ms = System.currentTimeMillis() - begin;

        double total = 0;
        for (DispatchThread t : crew) {    // results in a FIXED order, after join
            System.out.println(t.getName() + ": P" + t.getCollected());
            total = total + t.getCollected();
        }
        System.out.println("Total collected: P" + total);
        System.out.println("Finished in under 1 second? " + (ms < 1000));
    }
}

