public class BoardingTask implements Runnable {   // a JOB, not a thread
    private Vehicle vehicle;
    private int[] groups;                  // passengers arriving, group by group
    private String result = "not run yet";

    public BoardingTask(Vehicle vehicle, int[] groups) {
        this.vehicle = vehicle;
        this.groups = groups;
    }

    @Override
    public void run() {
        try {
            for (int g : groups) {
                vehicle.board(g);          // Week 13: may throw OverloadException
                Thread.sleep(50);
            }
            result = "all boarded";
        } catch (OverloadException e) {
            result = "stopped: " + e.getMessage();
        } catch (InterruptedException e) {
            result = "interrupted";
        }
    }

    public String getResult() { return result; }
}

public class Main {
    public static void main(String[] args) {
        Vehicle jeep = new Jeepney("NXA 123", "Mang Ramon", "Monumento-Divisoria");
        Vehicle trike = new Tricycle("TRC 456", "Kuya Ben", "Bagong Silang TODA");

        BoardingTask jeepJob = new BoardingTask(jeep, new int[] {5, 8, 6});
        BoardingTask trikeJob = new BoardingTask(trike, new int[] {2, 2, 1});

        Thread t1 = new Thread(jeepJob, "Jeep loader");  // job -> Thread
        Thread t2 = new Thread(trikeJob, "Trike loader");
        t1.start();
        t2.start();
        try {
            t1.join();
            t2.join();
        } catch (InterruptedException e) {
            System.out.println("main was interrupted");
        }
        System.out.println(t1.getName() + ": " + jeepJob.getResult());
        System.out.println(t2.getName() + ": " + trikeJob.getResult());
        jeep.showInfo();
        trike.showInfo();
    }
}

