import java.util.concurrent.CountDownLatch;

public class Cashier implements Runnable {
    private String name;
    private String[] items;
    private int[] prices;
    private int startDelay;
    private CountDownLatch done;
    private int total = 0;

    public Cashier(String name, String[] items, int[] prices,
                   int startDelay, CountDownLatch done) {
        this.name = name;
        this.items = items;
        this.prices = prices;
        this.startDelay = startDelay;
        this.done = done;
    }

    @Override
    public void run() {
        try {
            Thread.sleep(startDelay);
            for (int i = 0; i < items.length; i++) {
                total += prices[i];
                System.out.println(name + " rang up " + items[i] + " P" + prices[i]);
                Thread.sleep(200);
            }
        } catch (InterruptedException e) {
            System.out.println(name + " was interrupted");
        } finally {
            done.countDown();
        }
    }

    public int getTotal() { return total; }
}

import java.util.concurrent.CountDownLatch;

public class Main {
    public static void main(String[] args) {
        CountDownLatch done = new CountDownLatch(2);
        Cashier ana = new Cashier("Ana", new String[] {"Bread", "Rice"},
                new int[] {12, 55}, 0, done);
        Cashier ben = new Cashier("Ben", new String[] {"Soap", "Coffee"},
                new int[] {18, 9}, 100, done);
        new Thread(ana, "Ana's counter").start();
        new Thread(ben, "Ben's counter").start();
        try {
            done.await();
        } catch (InterruptedException e) {
            System.out.println("Closing early");
        }
        System.out.println("Ana's total: P" + ana.getTotal());
        System.out.println("Ben's total: P" + ben.getTotal());
        System.out.println("Store total: P" + (ana.getTotal() + ben.getTotal()));
    }
}

